sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float beatTime;
uniform float beatIndex;
uniform float strength;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
half4 main(float2 xy) {
    float k = strength * beat;
    if (k < 0.001) return image.eval(xy);
    float2 c = size * 0.5;
    half4 sum = half4(0.0);
    for (int i = 0; i < 16; i++) {
        sum += image.eval(c + (xy - c) * (1.0 - k * float(i) / 15.0));
    }
    return sum / 16.0;
}
